scwin.fn_test = function(dataObj) {
    console.log("dataObj : " + dataObj.value);
    var returnValue = "";
    if (parseInt(dataObj.value) == 0) {
        returnValue = "-";
    } else {
        returnValue = dataObj.value;
    }
    return returnValue;
};
