scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    pivotTable1.setOption({
        "rows": "",
        "cols": "",
        "vals": ""
    });
};
scwin.trigger2_onclick = function(e) {
    pivotTable1.setOption({
        "rows": "col2",
        "cols": "col1,col3,col6",
        "vals": "sDate,col4"
    });
};
scwin.formatter1 = function(info) {
    debugger;
    if (info.rowKey[0] == "광업 및 제조업1(C~D)" && info.colKey[0] == "2012") {
        return info.value + "%";
    }
    return info.value;
};
scwin.trigger3_onclick = function(e) {
    var excelOpt = {}; //excel download 옵션
    excelOpt.fileName = "excelData.xlsx"; //또는 xlsx 확장자 사용
    excelOpt.bodyFormat = "#,###";
    excelOpt.sumFormat = "#,###";
    pivotTable1.pivotExcelDownload(excelOpt);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
